package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** A steward merges a person into another: the merged person's claims move to the other (numbers and dates
 *  kept, listed after the other's in the order they were added, each losing any figure a statement bound), their
 *  name and aliases become the other's aliases, their patrons, the people naming them and their pool memberships
 *  pass to the other, and they leave the sheet (statements, holds, watchers and contact dropped). Refused for anyone
 *  but a steward, for the same person, and when either of them is retired. */
public class MergePerson {
    public void merge(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @RequestBody MergeRequest request, ServerHttpConnection connection, PersonRepository people,
            ClaimRepository claims, SettingsRepository settings, Audit audit, Rollup rollup, Out<Person> person)
            throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person from = people.find(id, pid);
        if (from == null) {
            throw new BadRequestException("no such person");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can merge people");
        }
        Person into = request == null || request.intoId() == null ? null : people.find(id, request.intoId());
        if (into == null) {
            throw new BadRequestException("choose the person to merge into");
        }
        if (into.id() == pid) {
            throw new BadRequestException("a person cannot be merged into themselves");
        }
        if (from.retired()) {
            throw new BadRequestException(from.name() + " is retired");
        }
        if (into.retired()) {
            throw new BadRequestException(into.name() + " is retired");
        }
        Rollup.Snapshot before = rollup.take(id);
        claims.moveAll(id, pid, into.id());
        people.merge(id, pid, into.id());
        audit.record("PERSON_MERGED sheet=" + id + " by=" + by + " from=" + from.name() + " into=" + into.name());
        rollup.record(id, by, before);
        person.set(people.find(id, into.id()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

import java.util.ArrayList;
import java.util.List;

/** A steward transfers a person to another sheet by id: they arrive there with every grade they were given (and
 *  its from-date), their terms, contact and aliases, and their claims (see {@link ClaimRepository#transferAll}), with
 *  no statements; they leave this sheet entirely (patron links, pool memberships, holds and watches dropped).
 *  A sheet id never used is made empty first, as loading it would. Refused for anyone but a steward, for a retired
 *  person, for this sheet's own id, and for an archived sheet. When their name or an alias is already a name or alias
 *  of someone on the other sheet, they are merged into that person there, as {@link MergePerson} does (claims after
 *  theirs, aliases joined, bound figures lost; refused when that person is retired or more than one person matches);
 *  otherwise refused when their name, an alias or their contact is already taken there. Each sheet writes its
 *  PERSON_TRANSFERRED line (the other sheet then PERSON_MERGED when merged), then its rollup lines. */
public class TransferPerson {
    public void transfer(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @RequestBody TransferRequest request, ServerHttpConnection connection, PersonRepository people,
            AliasRepository aliases, ClaimRepository claims, SettingsRepository settings, SheetRepository sheets, Audit audit,
            Rollup rollup,
            Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person from = people.find(id, pid);
        if (from == null) {
            throw new BadRequestException("no such person");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can transfer people");
        }
        if (from.retired()) {
            throw new BadRequestException(from.name() + " is retired");
        }
        String to = request == null || request.toSheetId() == null ? "" : request.toSheetId().trim();
        if (to.isEmpty()) {
            throw new BadRequestException("enter the sheet to transfer to");
        }
        if (to.equals(id)) {
            throw new BadRequestException("a person cannot be transferred to their own sheet");
        }
        if (settings.archived(to)) {
            throw new BadRequestException("sheet " + to + " is archived");
        }
        List<String> names = new ArrayList<>(List.of(from.name()));
        for (Alias alias : aliases.list(id)) {
            if (alias.personId() == pid) names.add(alias.alias());
        }
        Person into = null;
        for (String name : names) {
            Person match = people.findByName(to, name);
            if (match == null) continue;
            if (into != null && into.id() != match.id()) {
                throw new BadRequestException(name + " is already on sheet " + to);
            }
            into = match;
        }
        if (into != null) {
            if (into.retired()) {
                throw new BadRequestException(into.name() + " is retired");
            }
        } else {
            for (String name : names) {
                if (people.nameTaken(to, name, pid)) {
                    throw new BadRequestException(name + " is already on sheet " + to);
                }
            }
            if (from.contact() != null && people.contactTaken(to, from.contact(), 0)) {
                throw new BadRequestException(from.contact() + " is already on sheet " + to);
            }
        }

        if (!people.sheetExists(to)) {
            sheets.loadOrCreate(to, by);
        }
        Rollup.Snapshot beforeHere = rollup.take(id);
        Rollup.Snapshot beforeThere = rollup.take(to);
        long arrived;
        if (into == null) {
            arrived = people.transferIn(id, pid, to);
            claims.transferAll(id, pid, to, arrived);
        } else {
            // They arrive as merged into the person already there: their claims after that person's, their name
            // and aliases joined to that person's aliases.
            arrived = into.id();
            claims.transferAll(id, pid, to, arrived);
            people.joinAliases(to, arrived, names);
        }
        people.remove(id, pid);
        audit.record("PERSON_TRANSFERRED sheet=" + id + " by=" + by + " name=" + from.name() + " to=" + to);
        rollup.record(id, by, beforeHere);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + by + " name=" + from.name() + " from=" + id);
        if (into != null) {
            audit.record("PERSON_MERGED sheet=" + to + " by=" + by + " from=" + from.name() + " into=" + into.name());
        }
        rollup.record(to, by, beforeThere);
        person.set(people.find(to, arrived));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.history.HistoryRepository;
import net.officefloor.hq.app.history.SheetAsOf;
import net.officefloor.hq.app.person.Hold;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Take a person's statement: record their due-total now, and bind each claim of theirs that counts (a
 *  person's open (OPEN or PENDING) claims dated within a hold do not, unless already bound) to the figure it has now — its rate figure, not floored (a settled claim keeps its frozen due); a
 *  claim with no figure because the rate that would apply to it has ended is bound to n/a; a
 *  claim that does not count is unbound (live again). A late charge is never bound, nor is the floor: they keep following
 *  the sheet's today. The due-total is as shown: the sum of the counting claims' dues now (late charges
 *  included), skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today
 *  is in force then and no counting claim has a fixed figure or a due (at the grade it was claimed under); at
 *  most the sheet's cap.
 *
 *  <p>Taken as of a date (on or before the sheet's today; a later one is refused, as is one before the person
 *  was added), it binds the claims of theirs that counted at the end of that date to their figures as they
 *  stood then: every change made while the sheet's today was on or before that date counts, every later one
 *  does not, and that date stands in for the sheet's today in every figure (see {@link SheetAsOf}). Every
 *  other claim of theirs is unbound. The statement's date is that date, its due-total that day's, and its
 *  record ends with asof=<date>. */
public class TakeStatement {
    public void take(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @Val StatementInput input, ServerHttpConnection connection, PersonRepository people, ClaimRepository claims,
            SheetRepository sheets, SettingsRepository settings, HistoryRepository history, Audit audit, Rollup rollup,
            Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = people.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        LocalDate today = sheets.today(id);
        LocalDate asof = input.asof();
        if (asof != null) {
            if (today != null && asof.isAfter(today)) {
                throw new BadRequestException("a statement cannot be taken as of a date after the sheet's today (" + today + ")");
            }
            if (!history.existed(id, pid, asof)) {
                throw new BadRequestException(found.name() + " was not on the sheet on " + asof);
            }
        }
        SheetAsOf then = asof == null ? null : history.asOf(id, asof);
        List<Hold> holds = then == null ? found.liveHolds(today == null ? null : today.toString()) : then.liveHolds(pid);
        Rollup.Snapshot before = rollup.take(id);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int count = 0;
        for (Claim live : claims.ofPerson(id, pid)) {
            // As of a date, the claim as it stood then: absent when it was added later, or was another's then.
            Claim c = then == null ? live : then.claims().get(live.id());
            if (c == null || c.personId() != pid || !c.counts(holds)) {
                claims.bind(id, live.id(), false, null, false);
                continue;
            }
            count++;
            fixed |= c.fixed();
            // The claim is bound to its figure; its late charge is not bound, but counts in the due-total.
            BigDecimal figure = then == null ? claims.figure(id, c) : then.figure(c);
            BigDecimal now = then == null ? claims.dueNow(id, c) : then.dueNow(c);
            if (now != null) {
                total = total.add(now);
                fixed = true;
            }
            // With no figure (no rate applies, or it is bound to n/a already) it is bound to n/a: it stays
            // n/a even once a rate is in force on its date (a later rate, or a new grade for its person then).
            boolean na = figure == null;
            claims.bind(id, c.id(), true, figure, na);
        }
        boolean rated = then == null ? claims.rated(id, pid, today) : then.rated(pid);
        BigDecimal cap = then == null ? settings.cap(id) : then.cap();
        String dueTotal = fixed || rated ? SettingsRepository.capped(total, cap).setScale(2).toPlainString() : "n/a";
        people.stated(id, pid, dueTotal, asof == null ? today : asof);
        audit.record("STATEMENT sheet=" + id + " by=" + by + " name=" + found.name() + " due-total=" + dueTotal
                + " claims=" + count + (asof == null ? "" : " asof=" + asof));
        rollup.record(id, by, before);
        person.set(people.find(id, pid));
    }
}
-- A person's statements: how many have been taken, and the last one's due-total (as shown, so
-- possibly 'n/a') and date (the sheet's today when it was taken). Null until the first statement.
ALTER TABLE person ADD COLUMN statement_count BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(20);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim bound by its person's last statement: it shows and totals stated_due (the figure it had
-- then; null when it had none, its due then staying live) until the next statement rebinds or
-- unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
-- A claim a statement bound to n/a: it had no due then because the rate that would apply to it had
-- ended (its date after that rate's to-date). It shows and totals as n/a (a total skips it) until the
-- next statement rebinds or unbinds it, even once a later rate is in force on its date. (A claim
-- bound with no figure for want of any rate keeps a live due, as before.)
ALTER TABLE claim ADD COLUMN stated_na BOOLEAN DEFAULT FALSE NOT NULL;
-- Each statement taken of a person, numbered 1, 2, ... in the order taken, with its due-total (as shown,
-- so possibly 'n/a') and date. The person's stated_total and statement_date are those of the highest
-- numbered one; cancelling the last statement removes it, and the person then shows the one before it
-- (or nothing). A statement taken before this table only has its last one recorded.
CREATE TABLE person_statement (
    sheet_id       VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id      BIGINT NOT NULL,
    seq            BIGINT NOT NULL,
    due_total      VARCHAR(20),
    statement_date DATE NOT NULL,
    PRIMARY KEY (sheet_id, person_id, seq)
);
INSERT INTO person_statement (sheet_id, person_id, seq, due_total, statement_date)
    SELECT sheet_id, id, statement_count, stated_total, statement_date FROM person
    WHERE statement_count > 0 AND statement_date IS NOT NULL;

